command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="b414e8e3f8eb5e6c771c1f41ba4e632c143b1db4"
$built="c5bf4c4a2423bd378a9f02b31aa7b246aa93557e"
$candidate="1c8c3a8689157ba5eb3eaf7846e8626a03b252ea"
$branch="work/shell-provider-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider baseline retry fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before provider baseline retry"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "provider baseline retry candidate mismatch"}
& git diff --quiet $built $candidate -- app/winui
if($LASTEXITCODE -ne 0){throw "product input changed after successful baseline build"}
& git switch --detach $candidate
if($LASTEXITCODE -ne 0){throw "provider baseline retry checkout failed"}
$exe=Join-Path $repo "out\winui\Release\flyExplorer.exe"
if(-not(Test-Path -LiteralPath $exe -PathType Leaf)){throw "accepted baseline Release binary is missing"}
& python -X utf8 tests\winui\test_shell_provider_visual_gui.py --configuration Release --capture before
if($LASTEXITCODE -ne 0){throw "provider baseline GUI retry failed"}
$before=Join-Path $repo "logs\shell-provider-visual\shell-provider-visual-before.bmp"
if(-not(Test-Path -LiteralPath $before -PathType Leaf)){throw "provider baseline capture missing"}
$evidence=Join-Path $repo "logs\remote-evidence"
New-Item -ItemType Directory -Force -Path $evidence|Out-Null
Copy-Item -LiteralPath $before -Destination (Join-Path $evidence "shell-provider-visual-before.bmp") -Force
Write-Host ("SHELL_PROVIDER_BASELINE_SHA256="+(Get-FileHash -Algorithm SHA256 $before).Hash.ToLowerInvariant())
& git switch main
if($LASTEXITCODE -ne 0){throw "failed to restore main after provider baseline retry"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "failed to fast-forward main after provider baseline retry"}
Write-Host "SHELL_PROVIDER_VISUAL_BASELINE=PASS"
